def merge_duplicate_threads(apps, schema_editor):
    """Fusionne les fils multiples d'une meme paire avant la contrainte.

    La version precedente ouvrait un fil par annonce. Repasser a un fil par
    membre laisserait des doublons que la contrainte unique refuserait
    d'appliquer — et surtout, on ne peut pas supprimer ces fils : ils
    contiennent de vrais messages. On les fusionne donc dans le plus ancien,
    qui garde l'historique complet.
    """
    Conversation = apps.get_model("messaging", "Conversation")
    Message = apps.get_model("messaging", "Message")
    ConversationBlock = apps.get_model("messaging", "ConversationBlock")

    vus = {}
    for conversation in Conversation.objects.order_by("id"):
        cle = (conversation.participant_low_id, conversation.participant_high_id)
        garde = vus.get(cle)
        if garde is None:
            vus[cle] = conversation
            continue
        Message.objects.filter(conversation=conversation).update(conversation=garde)
        ConversationBlock.objects.filter(conversation=conversation).delete()
        if garde.initial_product_id is None and conversation.initial_product_id is not None:
            garde.initial_product_id = conversation.initial_product_id
            garde.save(update_fields=["initial_product"])
        conversation.delete()


